// EMBER "Ask the Flame": retrieval-grounded answers from NASA PSI content, with a red-team pass.
// Runs as a Vercel serverless function (POST /api/ask). The Gemini key stays server-side (env GEMINI_API_KEY).
// Guardrails: answers only from retrieved PSI context; citations are verified against that context;
// numbers must come from the context; risk is never softened (red-team section is mandatory).
// SI disclosure: written with assistance from Claude (Anthropic). Answers are generated by Google Gemini.
import fs from 'node:fs'
import path from 'node:path'

const DATA = path.join(process.cwd(), 'web', 'public', 'data')
let cache
function load() {
  if (!cache) {
    const read = f => JSON.parse(fs.readFileSync(path.join(DATA, f), 'utf8'))
    cache = { invs: read('investigations.json'), tests: read('tests.json'), meta: read('meta.json') }
    cache.docs = cache.invs.map(i => ({
      id: i.accession,
      text: [i.acronym, i.title, i.subArea, i.objective, i.approach, i.hypothesis, i.impacts, i.hardware, i.fuels.join(' '), i.fuelClasses.join(' '), i.pillars.join(' ')].filter(Boolean).join('\n'),
    }))
    const df = {}
    cache.docs.forEach(d => { d.tf = tok(d.text); new Set(Object.keys(d.tf)).forEach(w => (df[w] = (df[w] || 0) + 1)) })
    cache.df = df
    cache.avg = cache.docs.reduce((a, d) => a + (d.tf._len || 0), 0) / cache.docs.length
  }
  return cache
}
const STOP = new Set('the a an of and or to in on for with is are was were be by as at from that this it its into what how why which can do does we our their than then there these those will would should about under over'.split(' '))
function tok(s) {
  const tf = {}; let len = 0
  for (const w of String(s).toLowerCase().match(/[a-z0-9₂\-]+/g) || []) { if (STOP.has(w) || w.length < 2) continue; tf[w] = (tf[w] || 0) + 1; len++ }
  Object.defineProperty(tf, '_len', { value: len })
  return tf
}
function retrieve(q, k = 6) {
  const c = load(), qt = Object.keys(tok(q)), N = c.docs.length
  return c.docs.map(d => {
    const len = d.tf._len || 1
    let s = 0
    for (const w of qt) {
      const f = d.tf[w] || 0; if (!f) continue
      const idf = Math.log(1 + (N - (c.df[w] || 0) + 0.5) / ((c.df[w] || 0) + 0.5))
      s += idf * (f * 2.2) / (f + 1.2 * (0.25 + 0.75 * len / (c.avg || 1)))
    }
    return { id: d.id, s }
  }).sort((a, b) => b.s - a.s).slice(0, k).filter(x => x.s > 0)
}
function zone(tests, h, tO = 4, tP = 2) {
  const by = { solid: 0, liquid: 0, gas: 0, aerosol: 0 }; const inv = new Set()
  for (const t of tests) {
    if (t.matrix || t.o2Pct == null || t.pressurePsi == null || t.o2Basis === 'oxidizer-stream') continue
    if (Math.abs(t.o2Pct - h.o2) <= tO && Math.abs(t.pressurePsi - h.psi) <= tP) { by[t.fuelClass] += t.count || 1; inv.add(t.inv) }
  }
  return { by, investigations: [...inv] }
}

const SCHEMA = {
  type: 'OBJECT',
  properties: {
    answer: { type: 'STRING', description: 'Direct answer in plain English, 2-6 short paragraphs or bullet lines. Cite like [PSI-69].' },
    confidence: { type: 'STRING', enum: ['high', 'medium', 'low', 'no-data'] },
    citations: { type: 'ARRAY', items: { type: 'STRING' } },
    redTeam: {
      type: 'OBJECT',
      properties: {
        worstCase: { type: 'STRING', description: 'The worst credible fire scenario relevant to the question, stated plainly.' },
        gaps: { type: 'ARRAY', items: { type: 'STRING' }, description: 'Missing data or assumptions that limit the answer.' },
        doNotAssume: { type: 'STRING', description: 'One dangerous assumption an engineer must not make from this answer.' },
      },
      required: ['worstCase', 'gaps', 'doNotAssume'],
    },
  },
  required: ['answer', 'confidence', 'citations', 'redTeam'],
}

const SYSTEM = `You are EMBER, a fire-safety research assistant for engineers designing crewed spacecraft and Moon/Mars habitats.
Rules:
1. Use ONLY the NASA PSI context provided. If the context does not support an answer, say so and set confidence to "no-data".
2. Every factual sentence must cite its source: a PSI accession like [PSI-25], or [EMBER data] for COMPUTED FACTS. Never cite anything else.
3. Never invent numbers. Only quote numbers that appear in the context or in COMPUTED FACTS.
4. All PSI flight data is microgravity; there is no partial-gravity (Moon/Mars) combustion data in PSI. Say this whenever gravity matters.
5. Be risk-first: never soften, round down or omit a hazard. The redTeam section must state the worst credible case and data gaps honestly.
6. Rocket/propellant combustion is out of scope.
Write for aerospace engineers: precise, plain, no hype.`

async function body(req) {
  if (req.body && typeof req.body === 'object') return req.body
  const chunks = []; for await (const c of req) chunks.push(c)
  try { return JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}') } catch { return {} }
}

export default async function handler(req, res) {
  const send = (code, obj) => { res.statusCode = code; res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify(obj)) }
  if (req.method !== 'POST') return send(405, { error: 'POST only' })
  const key = process.env.GEMINI_API_KEY
  // Hedged requests: start the preferred model; if it hasn't answered after HEDGE_MS, also start the next one,
  // and so on. First valid answer wins; the rest are cancelled. Keeps answers fast during model demand spikes.
  const models = [...new Set([process.env.GEMINI_MODEL || 'gemini-3.5-flash',
    ...(process.env.GEMINI_FALLBACKS || 'gemini-3-flash-preview,gemini-3.5-flash-lite,gemini-3.1-flash-lite').split(',')].map(s => s.trim()).filter(Boolean))]
  if (!key) return send(503, { error: 'Server is missing GEMINI_API_KEY.' })

  const { question = '', habitat = null } = await body(req)
  const q = String(question).slice(0, 800).trim()
  if (q.length < 3) return send(400, { error: 'Ask a question.' })

  const c = load()
  const hits = retrieve(q + ' ' + (habitat?.name || ''), 6)
  const byId = Object.fromEntries(c.invs.map(i => [i.accession, i]))
  const ctx = hits.map(h => {
    const i = byId[h.id]
    return `### ${i.accession} · ${i.acronym || ''} · ${i.title}
DOI: ${i.doi || 'n/a'} | Type: ${i.projectType} | Pillars: ${i.pillars.join(', ')} | Hardware: ${i.hardware || 'n/a'}
Tests: ${i.nTests} | Fuels: ${i.fuels.slice(0, 12).join(', ')} | O2 range %: ${i.o2Range ? i.o2Range.map(v => v.toFixed(1)).join('-') : 'not in table'} | Pressure psi: ${i.pressureRange ? i.pressureRange.map(v => v.toFixed(1)).join('-') : 'not in table'}
Objective: ${(i.objective || '').slice(0, 1400)}
Approach: ${(i.approach || '').slice(0, 1200)}
Impacts: ${(i.impacts || '').slice(0, 600)}`
  }).join('\n\n')

  let facts = `Knowledge base: ${c.meta.investigations} PSI combustion investigations, ${c.meta.testRecords} test records, harvested ${c.meta.harvestedAt}.`
  if (habitat && Number.isFinite(+habitat.o2) && Number.isFinite(+habitat.psi)) {
    const z = zone(c.tests, { o2: +habitat.o2, psi: +habitat.psi })
    const solidMax = Math.max(...c.tests.filter(t => t.fuelClass === 'solid' && t.o2Pct).map(t => t.o2Pct))
    facts += `\nSelected habitat: ${habitat.name} at ${habitat.o2}% O2, ${habitat.psi} psi, ${habitat.g ?? 0} g.`
    facts += `\nTests within ±4 points O2 and ±2 psi of it (ambient O2): solid ${z.by.solid}, liquid ${z.by.liquid}, gas ${z.by.gas}; from ${z.investigations.join(', ') || 'none'}.`
    facts += `\nHighest O2 at which any solid material was tested in PSI: ${solidMax.toFixed(1)}%.`
  }
  { // always-on coverage fact: tests at elevated O2 (>=25%, ambient) AND reduced pressure (<=12 psi)
    const hi = {}
    for (const t of c.tests) if (!t.matrix && t.o2Pct != null && t.pressurePsi != null && t.o2Basis === 'measured' && t.pressureBasis === 'measured' && t.o2Pct >= 25 && t.pressurePsi <= 12) {
      const h = (hi[t.inv] ||= { n: 0, o2: [99, 0], p: [99, 0], cls: new Set() })
      h.n += t.count || 1; h.o2 = [Math.min(h.o2[0], t.o2Pct), Math.max(h.o2[1], t.o2Pct)]; h.p = [Math.min(h.p[0], t.pressurePsi), Math.max(h.p[1], t.pressurePsi)]; h.cls.add(t.fuelClass)
    }
    const list = Object.entries(hi).map(([id, h]) => `${id} (${byId[id]?.acronym || ''}): ${h.n} ${[...h.cls].join('/')} tests, ${h.o2[0].toFixed(0)}-${h.o2[1].toFixed(0)}% O2, ${h.p[0].toFixed(1)}-${h.p[1].toFixed(1)} psi`)
    facts += `\nAll PSI tests at elevated O2 (>=25%) AND reduced pressure (<=12 psi), measured: ${list.join('; ') || 'none'}. No solid-material test meets both conditions.`
    for (const id of Object.keys(hi)) if (!hits.some(h => h.id === id)) hits.push({ id, s: 0.01 }) // make sure they are citable
  }

  const prompt = `QUESTION: ${q}\n\nCOMPUTED FACTS (from EMBER's harvest of PSI tables):\n${facts}\n\nNASA PSI CONTEXT:\n${ctx || '(no matching investigations found)'}`
  const tried = []
  const controllers = []
  async function callGemini(m, ms) {
    const ac = new AbortController(); controllers.push(ac); const timer = setTimeout(() => ac.abort(), ms)
    try {
      const r = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(m)}:generateContent`, {
        method: 'POST', signal: ac.signal,
        headers: { 'Content-Type': 'application/json', 'x-goog-api-key': key },
        body: JSON.stringify({
          systemInstruction: { parts: [{ text: SYSTEM }] },
          contents: [{ role: 'user', parts: [{ text: prompt }] }],
          generationConfig: { temperature: 0.2, responseMimeType: 'application/json', responseSchema: SCHEMA },
        }),
      })
      const j = await r.json()
      if (!r.ok) throw new Error(j.error?.message || `HTTP ${r.status}`)
      const text = j.candidates?.[0]?.content?.parts?.filter(p => !p.thought).map(p => p.text).join('') || ''
      return JSON.parse(text)
    } finally { clearTimeout(timer) }
  }
  try {
    const HEDGE_MS = +(process.env.GEMINI_HEDGE_MS || 7000), BUDGET = 27000, t0 = Date.now()
    const { out, used } = await new Promise(resolve => {
      let done = false, pending = 0, next = 0, timer = null
      const launch = () => {
        if (done || next >= models.length) return
        const m = models[next++], left = BUDGET - (Date.now() - t0)
        if (left < 3000) return
        pending++
        callGemini(m, left).then(o => {
          if (!done) { done = true; clearTimeout(timer); controllers.forEach(c => c.abort()); resolve({ out: o, used: m }) }
        }).catch(e => {
          if (!done) tried.push(`${m}: ${e.name === 'AbortError' ? 'timed out' : String(e.message).slice(0, 120)}`)
          pending--
          if (!done) { clearTimeout(timer); launch(); if (pending === 0 && next >= models.length) { done = true; resolve({}) } else schedule() }
        })
      }
      const schedule = () => { clearTimeout(timer); if (next < models.length) timer = setTimeout(() => { launch(); schedule() }, HEDGE_MS) }
      launch(); schedule()
    })
    if (!out) return send(502, { error: 'The AI service is busy right now (all Gemini models failed). Please try again in a moment. ' + tried.join(' | ') })
    const allowed = new Set(hits.map(h => h.id))
    const cited = [...new Set([...(out.citations || []), ...((out.answer || '').match(/PSI-\d+/g) || [])])]
    out.citations = cited.filter(id => allowed.has(id))
    out.unverifiedCitations = cited.filter(id => /^PSI-\d+$/.test(id) && !allowed.has(id))
    out.sources = hits.map(h => ({ id: h.id, title: byId[h.id].title, acronym: byId[h.id].acronym, doi: byId[h.id].doi, relevance: +h.s.toFixed(2) }))
    out.model = used
    out.fallbacks = tried
    out.facts = facts
    return send(200, out)
  } catch (e) {
    return send(500, { error: 'Answer failed: ' + e.message })
  }
}
